#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int compare(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int weights[1000];
    int n = 0;
    int val;

    while (scanf("%d", &val) == 1) {
        weights[n++] = val;
    }

    qsort(weights, n, sizeof(int), compare);

    printf("Sorted package weights:");
    for (int i = 0; i < n; i++) {
        printf(" %d", weights[i]);
    }
    printf("\n");

    return 0;
}
